import { spaces, machines, panes, terminals, run, openOverlay, exec, hc, theme, shared, setShared, watchFolder, window, layout, pickFolder } from "herdr";

// Spaces that show an OpenRig team: a live terminal there runs `tmux attach -t =<seat>@<rig>`.
function rigSpaces() {
  const map = {};
  for (const k of terminals()) {
    if (k.state !== "live") continue;
    const argv = k.argv ?? [], i = argv.indexOf("attach");
    const rig = i >= 0 && argv[i + 1] === "-t" ? /^=[^@]+@(.+)$/.exec(argv[i + 2] ?? "")?.[1] : null;
    // Labels on another machine omit its "<machine>/" prefix; the app's space ids carry it.
    const pre = k.address.includes("/") ? k.address.slice(0, k.address.indexOf("/") + 1) : "";
    const space = k.labels?.["herdr.space"] ? pre + k.labels["herdr.space"] : null;
    if (rig && space && argv.includes("tmux")) map[space] ??= rig;
  }
  return map;
}

// A new space on another machine starts in that machine's home. Herdr leaves the folder
// empty and herdr-core then uses its own working folder instead, which on WSL is wherever
// the core was first started (often a /mnt/c/... folder of the Windows app that started it).
function newSpaceOn(m) {
  if (!m) return run("space.new", { machine: "" });
  exec("sh", ["-c", 'printf %s "$HOME"'], { on: m, timeout: 10000 })
    .then(r => { const home = String(r?.stdout ?? "").trim(); run("space.new", home.startsWith("/") ? { machine: m, folder: home } : { machine: m }); })
    .catch(() => run("space.new", { machine: m }));
}
